  } catch {
    throw new Error(`${step}: response was not JSON (HTTP ${response.status}): ${text.slice(0, 500)}`);
  }
}

async function requireJson(response, step) {
  const body = await jsonBody(response, step);
  if (!response.ok || body.success === false) {
